        catch (JsonException)
        {
            return null;
        }
    }

    private HttpRequestMessage BuildMessage(TungoRequest request, Uri uri, RequestOptions? options, string? idempotencyKey, string idempotencyHeader, bool streaming)
    {
        var message = new HttpRequestMessage(request.Method, uri);
        try
        {
            if (request.Body is not null)
            {
                message.Content = new ByteArrayContent(request.Body);
                message.Content.Headers.TryAddWithoutValidation("Content-Type", request.ContentType ?? "application/json");
            }

            foreach (var header in _defaultHeaders)
            {
                // A default credential header must not leak to public endpoints and hooks.
                if ((request.Auth != TungoAuth.ApiKey && IsCredentialHeader(header.Key)) || IsUndeclaredKey(request, header.Key))
                {
                    continue;
                }

                SetHeader(message, header.Key, header.Value);
            }

            SetHeader(message, "Accept", streaming ? "text/event-stream" : "application/json");
            SetHeader(message, "User-Agent", TungoSdkInfo.UserAgent);
            if (request.Auth == TungoAuth.ApiKey)
            {
                SetHeader(message, "x-api-key", _apiKey!);
            }

            if (idempotencyKey is not null)
            {
                SetHeader(message, idempotencyHeader, idempotencyKey);
            }

            foreach (var header in request.Headers)
            {
                SetHeader(message, header.Key, header.Value);
            }

            if (options?.Headers is not null)
            {
                foreach (var header in options.Headers)
                {
                    if (IsUndeclaredKey(request, header.Key))
                    {
                        continue;
                    }

                    SetHeader(message, header.Key, header.Value);
                }
            }

            return message;
        }
        catch
        {
            message.Dispose();
            throw;
        }
    }

    private static bool IsUndeclaredKey(TungoRequest request, string name)
    {
        return request.IdempotencyHeader is null && string.Equals(name, "Idempotency-Key", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsCredentialHeader(string name)
    {
        return string.Equals(name, "x-api-key", StringComparison.OrdinalIgnoreCase)
            || string.Equals(name, "Authorization", StringComparison.OrdinalIgnoreCase);
    }

    private static void SetHeader(HttpRequestMessage message, string name, string value)
    {
        CheckHeader(name, value);
        if (name.StartsWith("Content-", StringComparison.OrdinalIgnoreCase))
        {
            if (message.Content is not null)
            {
                message.Content.Headers.Remove(name);
                message.Content.Headers.TryAddWithoutValidation(name, value);
            }

            return;
        }

        message.Headers.Remove(name);
        if (!message.Headers.TryAddWithoutValidation(name, value))
        {
            throw new TungoValidationException("The header '" + name + "' cannot be set on a request.");
        }
    }

    private static void CheckHeader(string name, string value)
    {
        if (string.IsNullOrEmpty(name) || value is null || name.IndexOfAny(LineBreaks) >= 0 || value.IndexOfAny(LineBreaks) >= 0)
        {
            throw new TungoValidationException("The header '" + (name ?? string.Empty).Replace("\r", string.Empty).Replace("\n", string.Empty) + "' has an empty name, no value or a line break.");
        }
    }

    private static readonly char[] LineBreaks = { '\r', '\n' };

    private static TimeSpan CheckTimeout(TimeSpan value, string name)
    {
        if (value != Timeout.InfiniteTimeSpan && (value <= TimeSpan.Zero || value.TotalMilliseconds > int.MaxValue))
        {
            throw new TungoValidationException(name + " must be positive (or Timeout.InfiniteTimeSpan to disable the limit).");
        }

        return value;
    }

    /// <summary>
    /// A caller's <see cref="HttpClient" /> has its own time limit (100 s unless changed) that ends a request before the
    /// response headers arrive, whatever the SDK's limits say: a chat turn that may take <paramref name="chatTimeout" /> would be cut.
    /// </summary>
    private static void CheckClientTimeout(TimeSpan clientTimeout, TimeSpan timeout, TimeSpan chatTimeout)
    {
        if (clientTimeout == Timeout.InfiniteTimeSpan)
        {
            return;
        }

        var unlimited = timeout == Timeout.InfiniteTimeSpan || chatTimeout == Timeout.InfiniteTimeSpan;
        var longest = timeout > chatTimeout ? timeout : chatTimeout;
        if (unlimited || clientTimeout < longest)
        {
            throw new TungoConfigurationException(
                "The HttpClient passed in TungoClientOptions.HttpClient has Timeout = " + FormatSeconds(clientTimeout) + " s, shorter than the SDK's time limit of "
                + (unlimited ? "unlimited" : FormatSeconds(longest) + " s")
                + " (TungoClientOptions.Timeout and ChatTimeout): it would cut long requests such as chat turns. Set httpClient.Timeout = Timeout.InfiniteTimeSpan; the SDK enforces its own time limit on every request.");
        }
    }

    /// <summary>
    /// A response that comes from another origin than the request went to means the HTTP client followed a redirect, and
    /// took the API key along. The SDK's own handler never does; for a caller's client this is the only place to notice.
    /// </summary>
