    {
        var answered = message.RequestMessage?.RequestUri;
        if (answered is null || !answered.IsAbsoluteUri)
        {
            return;
        }

        if (string.Equals(answered.Scheme, sent.Scheme, StringComparison.OrdinalIgnoreCase)
            && string.Equals(answered.Host, sent.Host, StringComparison.OrdinalIgnoreCase)
            && answered.Port == sent.Port)
        {
            return;
        }

        throw new TungoConfigurationException(
            "The HTTP client followed a redirect from " + sent.GetLeftPart(UriPartial.Authority) + " to " + answered.GetLeftPart(UriPartial.Authority)
            + " while sending " + request.Method.Method + " " + request.Route + "; the response was discarded. A followed redirect carries the request headers, including the API key, to the host it names: "
            + "set AllowAutoRedirect = false on the handler of the HttpClient passed in TungoClientOptions.HttpClient.");
    }

    private static bool IsTransportFailure(Exception e)
    {
        return e is HttpRequestException or IOException or OperationCanceledException or ObjectDisposedException or SocketException;
    }

